import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { sheetKey } from './sheetQuery';
import type { Sheet } from './sheetQuery';
import { useSheetToday } from './useSheetToday';

function SheetToday({ sheetId }: { sheetId: string }) {
  const today = useSheetToday(sheetId);
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState('');
  const [error, setError] = useState('');

  const save = useMutation({
    mutationFn: (date: string) =>
      putJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today: date }),
    onSuccess: (sheet) => queryClient.setQueryData(sheetKey(sheetId), sheet),
    onError: () => setError('That is not a date (yyyy-mm-dd).'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    save.mutate(typed.trim());
  };

  return (
    <form data-testid="sheet-today-form" onSubmit={submit}>
      Today <strong data-testid="sheet-today">{today}</strong>{' '}
      <label>
        Change to{' '}
        <input
          data-testid="sheet-today-input"
          placeholder="yyyy-mm-dd"
          value={typed}
          onChange={(e) => {
            setTyped(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save">
        Set today
      </button>
      {error && <p data-testid="sheet-error">{error}</p>}
    </form>
  );
}

// Keyed by sheet, so a typed date or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 0,
  Component: ({ sheetId }) => <SheetToday key={sheetId} sheetId={sheetId} />,
});
  const rates = useQuery(ratesQuery(sheetId));
  const [grade, setGrade] = useState<Grade>('A');
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const today = useSheetToday(sheetId);
  const [error, setError] = useState('');

  const [user] = useUser();
  const save = useMutation({
    mutationFn: (body: { grade: Grade; rate: string; from: string }) =>
      putJson<Rate>(
        `/api/sheets/${encodeURIComponent(sheetId)}/rates/${body.grade}`,
        { rate: body.rate, from: body.from },
        user,
      ),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
      setPct('');
      setFrom('');
    },
    onError: () => setError('The rate could not be set.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const p = pct.trim();
    if (!PERCENT.test(p)) {
      setError('The rate must be a percent of 0.00 or more, with up to two decimals.');
      return;
    }
    const f = from.trim();
    if (f !== '' && !DATE.test(f)) {
      setError('The from-date must be a date (yyyy-mm-dd).');
      return;
    }
    save.mutate({ grade, rate: p, from: f });
  };

  const list = rates.data ?? [];
  return (
/**
 * A claim's status and the buttons that change it. Every button is offered; the server refuses a
 * change the status does not allow, or a settle by the user who opened the claim, and the refusal
 * shows on the claim until its next action.
 */
function ClaimStatusCell({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [error, setError] = useState('');
  const change = useMutation({
    mutationFn: (to: ClaimStatus) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/status/${to}`, {}, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
    onError: (_e, to) =>
      setError(
        to === 'SETTLED' && claim.status === 'OPEN' && claim.openedBy === user
          ? 'The user who opened a claim cannot settle it.'
          : `A ${claim.status} claim cannot become ${to}.`,
      ),
  });

  return (
    <td>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, to, label }) => (
        <button
          key={action}
          type="button"
          data-testid={`claim-${action}`}
          disabled={change.isPending}
          onClick={() => {
            setError('');
            change.mutate(to);
          }}
        >
          {label}
        </button>
      ))}
      {error && <span data-testid="claim-error">{error}</span>}
    </td>
  );
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;

